<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { CalendarDays, ExternalLink, MessageCircle, TrendingDown, TrendingUp } from 'lucide-vue-next'
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue'
import AdminState from '../../components/admin/AdminState.vue'
import { getAdminCourses, getAttendances } from '../../services/adminApi'

const loading = ref(true); const error = ref(''); const attendance = ref(null); const courses = ref([]); const filters = ref({ start_date: '', end_date: '', course_id: '', utm_source: '', origin: '', page: 1, per_page: 15 })
const changeLabel = computed(() => { const value = attendance.value?.summary?.change_percentage; return value === null || value === undefined ? 'Sem base anterior' : `${value > 0 ? '+' : ''}${value}%` })
function load(page = filters.value.page) { filters.value.page = page; loading.value = true; error.value = ''; return getAttendances(filters.value).then((payload) => { attendance.value = payload }).catch((requestError) => { error.value = requestError.message }).finally(() => { loading.value = false }) }
onMounted(async () => { try { const courseData = await getAdminCourses({ per_page: 50, sort: 'name', direction: 'asc' }); courses.value = courseData.data; await load() } catch (requestError) { error.value = requestError.message; loading.value = false } })
watch(() => [filters.value.start_date, filters.value.end_date, filters.value.course_id, filters.value.utm_source, filters.value.origin], () => load(1))
function dateTime(value) { return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) }
</script>

<template><AdminPageHeader title="Atendimentos" description="Leitura operacional dos cliques que levam os interessados ao WhatsApp." /><section class="admin-filter-card compact"><div class="admin-filter-row"><label><span>De</span><input v-model="filters.start_date" type="date" /></label><label><span>Até</span><input v-model="filters.end_date" type="date" /></label><label><span>Curso</span><select v-model="filters.course_id"><option value="">Todos os cursos</option><option v-for="course in courses" :key="course.id" :value="course.id">{{ course.name }}</option></select></label><label><span>UTM source</span><input v-model="filters.utm_source" placeholder="Ex.: instagram" /></label><label><span>Origem</span><input v-model="filters.origin" placeholder="Parte da URL" /></label></div></section><AdminState v-if="loading" message="Carregando atendimentos…" /><AdminState v-else-if="error" type="error" :message="error" /><template v-else><section class="admin-stat-grid attendance"><article><span class="stat-icon purple"><MessageCircle :size="20" /></span><div><p>Total de cliques</p><strong>{{ attendance.summary.total_clicks }}</strong><small>{{ attendance.period.start_date }} a {{ attendance.period.end_date }}</small></div></article><article><span class="stat-icon blue"><CalendarDays :size="20" /></span><div><p>Período anterior</p><strong>{{ attendance.summary.previous_period_clicks }}</strong><small>para comparação</small></div></article><article><span class="stat-icon" :class="attendance.summary.change_percentage >= 0 ? 'green' : 'red'"><TrendingUp v-if="attendance.summary.change_percentage >= 0" :size="20" /><TrendingDown v-else :size="20" /></span><div><p>Variação</p><strong>{{ changeLabel }}</strong><small>comparação simples</small></div></article></section><section class="admin-dashboard-grid analytics"><article class="admin-card"><div class="card-heading"><div><h2>Por curso</h2><p>Principais origens de interesse.</p></div></div><AdminState v-if="!attendance.summary.by_course.length" type="empty" message="Ainda não há cliques no período." /><ol v-else class="rank-list"><li v-for="item in attendance.summary.by_course" :key="item.course_id"><span>{{ item.course }}</span><strong>{{ item.total }}</strong></li></ol></article><article class="admin-card"><div class="card-heading"><div><h2>Por modalidade</h2><p>Formação e Atualização.</p></div></div><AdminState v-if="!attendance.summary.by_modality.length" type="empty" message="Ainda não há cliques no período." /><ol v-else class="rank-list"><li v-for="item in attendance.summary.by_modality" :key="item.modality_id"><span>{{ item.modality }}</span><strong>{{ item.total }}</strong></li></ol></article></section><section class="admin-table-card"><div class="table-card-title"><div><h2>Registros de clique</h2><p>Sem dados pessoais: apenas informações analíticas necessárias.</p></div></div><AdminState v-if="!attendance.clicks.data.length" type="empty" message="Os registros surgem quando visitantes clicam nos CTAs de WhatsApp." /><div v-else class="admin-table-wrap"><table><thead><tr><th>Curso</th><th>Modalidade</th><th>Origem</th><th>UTM</th><th>Data e hora</th></tr></thead><tbody><tr v-for="click in attendance.clicks.data" :key="click.id"><td>{{ click.course || '—' }}</td><td>{{ click.modality || '—' }}</td><td><a v-if="click.source_url" class="origin-link" :href="click.source_url" target="_blank" rel="noopener"><ExternalLink :size="15" />Ver página</a><span v-else>—</span></td><td><span v-if="Object.keys(click.utm).length" class="utm-text">{{ Object.entries(click.utm).map(([key, value]) => `${key}: ${value}`).join(' · ') }}</span><span v-else>—</span></td><td>{{ dateTime(click.created_at) }}</td></tr></tbody></table></div><div v-if="attendance.clicks.meta.last_page > 1" class="admin-pagination"><span>{{ attendance.clicks.meta.from }}–{{ attendance.clicks.meta.to }} de {{ attendance.clicks.meta.total }} registros</span><div><button class="admin-button ghost" :disabled="attendance.clicks.meta.current_page === 1" @click="load(attendance.clicks.meta.current_page - 1)">Anterior</button><button class="admin-button ghost" :disabled="attendance.clicks.meta.current_page === attendance.clicks.meta.last_page" @click="load(attendance.clicks.meta.current_page + 1)">Próxima</button></div></div></section></template></template>
